/* ============================================================
   Moss — a gentle plant-care companion
   Warm paper, soft shadows, expressive squishy shapes.
   Mobile-first. No external anything.
   ============================================================ */

:root {
  --paper:        #f7f0e2;
  --paper-2:      #fbf6ec;
  --card:         #fffdf7;
  --ink:          #35302a;
  --ink-soft:     #6b6155;
  --ink-faint:    #9a8f7f;

  --moss:         #4f7a4a;
  --moss-deep:    #3c6139;
  --moss-wash:    #e3eccc;
  --leaf:         #7fa663;
  --leaf-light:   #a9c47f;

  --clay:         #d9764f;
  --clay-deep:    #b85a38;
  --clay-wash:    #f6ddcb;

  --butter:       #e9b84a;
  --butter-wash:  #f7e7b8;
  --sky:          #8fb8bf;
  --sky-wash:     #dbe9e6;

  --line:         #e7dcc7;
  --line-strong:  #d8c9ac;

  --shadow-soft:  0 2px 0 rgba(63, 52, 36, .05), 0 10px 24px -14px rgba(63, 52, 36, .35);
  --shadow-lift:  0 3px 0 rgba(63, 52, 36, .07), 0 18px 34px -16px rgba(63, 52, 36, .4);

  --r-sm: 12px;
  --r-md: 18px;
  --r-lg: 26px;
  --r-pill: 999px;

  --ease-bounce: cubic-bezier(.34, 1.56, .64, 1);
  --ease-soft:   cubic-bezier(.22, 1, .36, 1);

  --font: "Iowan Old Style", "Palatino Linotype", "Book Antiqua", Palatino, "Georgia", "Times New Roman", serif;
  --font-ui: ui-rounded, "Segoe UI", "Avenir Next", Avenir, "Trebuchet MS", "Verdana", system-ui, sans-serif;
}

*, *::before, *::after { box-sizing: border-box; }

html { -webkit-text-size-adjust: 100%; scroll-behavior: smooth; }

body {
  margin: 0;
  min-height: 100vh;
  min-height: 100dvh;
  color: var(--ink);
  background: var(--paper);
  font-family: var(--font-ui);
  font-size: 16px;
  line-height: 1.55;
  -webkit-font-smoothing: antialiased;
  position: relative;
  overflow-x: hidden;
}

/* Soft paper grain, drawn with gradients only. */
body::before {
  content: "";
  position: fixed;
  inset: 0;
  pointer-events: none;
  z-index: 0;
  opacity: .5;
  background-image:
    radial-gradient(circle at 12% 22%, rgba(160, 140, 100, .07) 0 1px, transparent 1.5px),
    radial-gradient(circle at 68% 74%, rgba(160, 140, 100, .06) 0 1px, transparent 1.5px),
    radial-gradient(circle at 34% 88%, rgba(120, 100, 70, .05) 0 1px, transparent 1.5px);
  background-size: 37px 37px, 53px 53px, 61px 61px;
}

/* ------------------------------------------------------------
   Canvas decoration — big lazy blobs behind everything
   ------------------------------------------------------------ */
.canvas {
  position: fixed;
  inset: 0;
  z-index: 0;
  pointer-events: none;
  overflow: hidden;
}
.canvas-blob, .canvas-ring, .canvas-star { position: absolute; display: block; }
.canvas-blob { border-radius: 46% 54% 61% 39% / 55% 44% 56% 45%; }
.canvas-blob--a {
  width: 60vw; height: 60vw; max-width: 620px; max-height: 620px;
  top: -18vw; right: -18vw;
  background: radial-gradient(circle at 35% 35%, var(--moss-wash), #d5e3bd 70%, transparent 72%);
  opacity: .65;
  transform: rotate(18deg);
}
.canvas-blob--b {
  width: 46vw; height: 46vw; max-width: 460px; max-height: 460px;
  bottom: -16vw; left: -14vw;
  background: radial-gradient(circle at 60% 40%, var(--clay-wash), #f0cdb4 72%, transparent 74%);
  opacity: .6;
  border-radius: 58% 42% 38% 62% / 42% 58% 42% 58%;
}
.canvas-blob--c {
  width: 32vw; height: 32vw; max-width: 340px; max-height: 340px;
  top: 44%; left: 58%;
  background: radial-gradient(circle at 50% 50%, var(--butter-wash), transparent 72%);
  opacity: .5;
}
.canvas-ring {
  border: 2px solid var(--line-strong);
  border-radius: 50%;
  opacity: .5;
}
.canvas-ring--a { width: 120px; height: 120px; top: 16%; left: -60px; }
.canvas-ring--b { width: 70px; height: 70px; bottom: 22%; right: -28px; border-style: dashed; }
.canvas-star {
  color: var(--leaf-light);
  font-size: 22px;
  opacity: .6;
}
.canvas-star--a { top: 12%; left: 8%; transform: rotate(-16deg); }
.canvas-star--b { top: 30%; right: 12%; font-size: 16px; color: var(--clay); }
.canvas-star--c { bottom: 14%; left: 16%; font-size: 30px; color: var(--butter); }
.canvas-star--d { bottom: 38%; right: 6%; font-size: 13px; }

/* ------------------------------------------------------------
   Frame / layout
   ------------------------------------------------------------ */
.frame {
  position: relative;
  z-index: 1;
  width: min(100% - 32px, 1180px);
  margin-inline: auto;
  padding: clamp(20px, 4vw, 40px) 0 28px;
}

.skip-link {
  position: absolute;
  left: 12px;
  top: -80px;
  z-index: 100;
  background: var(--ink);
  color: var(--paper-2);
  padding: 10px 18px;
  border-radius: var(--r-pill);
  text-decoration: none;
  font-weight: 700;
  transition: top .2s var(--ease-soft);
}
.skip-link:focus { top: 12px; }

.sr-only {
  position: absolute !important;
  width: 1px; height: 1px;
  padding: 0; margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

/* ------------------------------------------------------------
   Brand
   ------------------------------------------------------------ */
.brand {
  display: flex;
  align-items: center;
  gap: 14px;
  padding: 4px 2px 26px;
}
.brand__mark {
  flex: none;
  width: 44px; height: 44px;
  background: var(--moss);
  border-radius: 58% 42% 40% 60% / 62% 58% 42% 38%;
  position: relative;
  box-shadow: inset -4px -5px 0 rgba(0, 0, 0, .08), 0 3px 0 rgba(63, 52, 36, .12);
  transform: rotate(-8deg);
}
.brand__mark::before, .brand__mark::after {
  content: "";
  position: absolute;
  background: var(--paper-2);
  border-radius: 90% 10% 90% 10%;
}
.brand__mark::before {
  width: 16px; height: 9px;
  top: 11px; left: 8px;
  transform: rotate(-32deg);
}
.brand__mark::after {
  width: 15px; height: 8px;
  top: 21px; right: 7px;
  transform: rotate(28deg) scaleX(-1);
}
.brand__text { flex: 1 1 auto; min-width: 0; }
.brand__eyebrow, .eyebrow {
  margin: 0;
  font-size: .66rem;
  letter-spacing: .18em;
  text-transform: uppercase;
  font-weight: 800;
  color: var(--moss-deep);
}
.brand__eyebrow { color: var(--ink-faint); }
.brand__name {
  margin: -2px 0 0;
  font-family: var(--font);
  font-weight: 700;
  font-size: clamp(2.1rem, 7vw, 2.9rem);
  line-height: 1;
  letter-spacing: -.04em;
  color: var(--ink);
}
.brand__dot { color: var(--clay); }
.brand__mascot {
  flex: none;
  width: 56px; height: 56px;
  display: grid;
  place-items: center;
  filter: drop-shadow(0 4px 5px rgba(63, 52, 36, .18));
}
.brand__mascot svg { width: 100%; height: 100%; }

/* ------------------------------------------------------------
   Layout — single column on mobile, distinct composition on desktop
   ------------------------------------------------------------ */
.layout { display: grid; gap: 28px; }

.queue__intro { position: relative; }
.greeting {
  font-family: var(--font);
  font-weight: 700;
  font-size: clamp(2rem, 8.5vw, 3.25rem);
  line-height: 1.02;
  letter-spacing: -.035em;
  margin: 10px 0 12px;
  max-width: 14ch;
}
.greeting em {
  font-style: italic;
  color: var(--moss);
  position: relative;
  white-space: nowrap;
}
.greeting em::after {
  content: "";
  position: absolute;
  left: 2%; right: 2%; bottom: -.06em;
  height: .1em;
  background: var(--butter);
  border-radius: var(--r-pill);
  transform: rotate(-1.5deg) scaleX(1);
  z-index: -1;
}
.lede {
  margin: 0;
  max-width: 46ch;
  color: var(--ink-soft);
  font-size: 1rem;
  line-height: 1.65;
}

.summary {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-top: 18px;
}
.chip {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  padding: 7px 13px 7px 9px;
  border-radius: var(--r-pill);
  background: var(--card);
  border: 1.5px solid var(--line);
  font-size: .8rem;
  font-weight: 700;
  color: var(--ink-soft);
  box-shadow: var(--shadow-soft);
}
.chip__dot {
  width: 9px; height: 9px;
  border-radius: 50%;
  flex: none;
}
.chip--overdue { background: var(--clay-wash); border-color: #ecb99d; color: var(--clay-deep); }
.chip--overdue .chip__dot { background: var(--clay); }
.chip--today .chip__dot { background: var(--moss); }
.chip--later .chip__dot { background: var(--sky); }

/* ------------------------------------------------------------
   Filter controls
   ------------------------------------------------------------ */
.queue__controls {
  margin: 28px 0 16px;
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
}
.segmented {
  display: inline-flex;
  padding: 5px;
  gap: 3px;
  background: var(--paper-2);
  border: 1.5px solid var(--line);
  border-radius: var(--r-pill);
  box-shadow: inset 0 1px 3px rgba(63, 52, 36, .06);
}
.seg {
  appearance: none;
  border: 0;
  background: transparent;
  color: var(--ink-soft);
  font: inherit;
  font-size: .84rem;
  font-weight: 700;
  padding: 8px 15px;
  border-radius: var(--r-pill);
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  gap: 7px;
  transition: background .25s var(--ease-soft), color .2s, transform .25s var(--ease-bounce);
}
.seg:hover { color: var(--ink); }
.seg[aria-pressed="true"] {
  background: var(--ink);
  color: var(--paper-2);
  box-shadow: 0 2px 0 rgba(63, 52, 36, .2);
}
.seg__count {
  font-size: .7rem;
  min-width: 18px; height: 18px;
  display: inline-grid;
  place-items: center;
  border-radius: var(--r-pill);
  background: rgba(63, 52, 36, .1);
  padding: 0 5px;
  font-variant-numeric: tabular-nums;
}
.seg[aria-pressed="true"] .seg__count { background: rgba(255, 255, 255, .22); }
.queue__hint {
  margin: 0;
  font-family: var(--font);
  font-style: italic;
  font-size: .9rem;
  color: var(--ink-faint);
}
.queue__hint span { color: var(--clay); font-size: 1.1rem; }

/* ------------------------------------------------------------
   Plant cards
   ------------------------------------------------------------ */
.cards {
  list-style: none;
  margin: 0;
  padding: 0;
  display: grid;
  gap: 14px;
}
.card {
  position: relative;
  background: var(--card);
  border: 1.5px solid var(--line);
  border-radius: var(--r-lg);
  box-shadow: var(--shadow-soft);
  transition: box-shadow .3s var(--ease-soft), transform .35s var(--ease-bounce), border-color .3s, opacity .35s;
  overflow: hidden;
}
.card:hover { box-shadow: var(--shadow-lift); }
.card::before {
  content: "";
  position: absolute;
  left: 0; top: 0; bottom: 0;
  width: 6px;
  background: var(--accent, var(--moss));
  border-radius: 0 6px 6px 0;
  opacity: .85;
}
.card--overdue { --accent: var(--clay); border-color: #eac2ad; }
.card--today   { --accent: var(--moss); }
.card--later   { --accent: var(--sky); }
.card--done {
  --accent: var(--leaf-light);
  background: var(--paper-2);
  border-style: dashed;
  box-shadow: none;
}
.card--done .card__art { filter: grayscale(.35) saturate(.7); opacity: .7; }
.card--done .card__name { text-decoration: line-through; text-decoration-color: var(--ink-faint); text-decoration-thickness: 2px; }
.card--snoozed { --accent: var(--butter); }
.card--fresh { animation: pop-in .5s var(--ease-bounce) both; }
@keyframes pop-in {
  from { opacity: 0; transform: translateY(14px) scale(.97); }
  to   { opacity: 1; transform: none; }
}

.card__head {
  width: 100%;
  display: grid;
  grid-template-columns: 64px 1fr auto;
  align-items: center;
  gap: 14px;
  padding: 14px 16px 14px 18px;
  background: transparent;
  border: 0;
  text-align: left;
  font: inherit;
  color: inherit;
  cursor: pointer;
  border-radius: var(--r-lg);
}
.card__head:hover .card__chevron { transform: translateY(2px); background: var(--moss-wash); }

.card__art {
  width: 64px; height: 64px;
  border-radius: 46% 54% 52% 48% / 50% 46% 54% 50%;
  background: var(--art-bg, var(--moss-wash));
  display: grid;
  place-items: center;
  overflow: hidden;
  flex: none;
  box-shadow: inset 0 -3px 6px rgba(63, 52, 36, .08);
}
.card__art svg { width: 100%; height: 100%; display: block; }

.card__id { min-width: 0; }
.card__namerow { display: flex; align-items: baseline; gap: 8px; flex-wrap: wrap; }
.card__name {
  font-family: var(--font);
  font-weight: 700;
  font-size: 1.35rem;
  letter-spacing: -.02em;
  margin: 0;
  line-height: 1.15;
}
.card__species {
  font-size: .78rem;
  color: var(--ink-faint);
  font-style: italic;
  font-family: var(--font);
}
.card__task {
  margin: 5px 0 0;
  font-size: .9rem;
  font-weight: 700;
  color: var(--ink-soft);
}
.card__task b { color: var(--ink); }

.card__meta { display: flex; flex-direction: column; align-items: flex-end; gap: 7px; flex: none; }
.badge {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-size: .7rem;
  font-weight: 800;
  letter-spacing: .04em;
  text-transform: uppercase;
  padding: 5px 10px;
  border-radius: var(--r-pill);
  white-space: nowrap;
}
.badge::before {
  content: "";
  width: 7px; height: 7px;
  border-radius: 50%;
  background: currentColor;
}
.badge--overdue { background: var(--clay-wash); color: var(--clay-deep); }
.badge--today   { background: var(--moss-wash); color: var(--moss-deep); }
.badge--later   { background: var(--sky-wash); color: #4d7a80; }
.badge--done    { background: var(--moss-wash); color: var(--moss-deep); }
.badge--snoozed { background: var(--butter-wash); color: #9a7413; }
.card__chevron {
  width: 28px; height: 28px;
  border-radius: 50%;
  background: var(--paper-2);
  border: 1.5px solid var(--line);
  display: grid;
  place-items: center;
  font-size: .8rem;
  color: var(--ink-soft);
  transition: transform .3s var(--ease-bounce), background .2s;
}
.card__head[aria-expanded="true"] .card__chevron { transform: rotate(180deg); background: var(--moss-wash); }

/* Expandable detail */
.card__detail {
  display: grid;
  grid-template-rows: 0fr;
  transition: grid-template-rows .4s var(--ease-soft);
}
.card__head[aria-expanded="true"] + .card__detail { grid-template-rows: 1fr; }
.card__detail-inner { overflow: hidden; min-height: 0; }
.card__detail-pad { padding: 0 18px 18px; }

.facts {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 10px;
  margin: 0 0 14px;
}
.fact {
  background: var(--paper-2);
  border: 1.5px solid var(--line);
  border-radius: var(--r-md);
  padding: 10px 12px;
}
.fact dt {
  font-size: .64rem;
  letter-spacing: .14em;
  text-transform: uppercase;
  font-weight: 800;
  color: var(--ink-faint);
  display: flex;
  align-items: center;
  gap: 6px;
}
.fact dd {
  margin: 3px 0 0;
  font-size: .9rem;
  font-weight: 700;
  color: var(--ink);
}
.fact__icon { font-size: .95rem; }

.history-title {
  margin: 0 0 8px;
  font-size: .64rem;
  letter-spacing: .14em;
  text-transform: uppercase;
  font-weight: 800;
  color: var(--ink-faint);
}
.history { list-style: none; margin: 0 0 16px; padding: 0; display: grid; gap: 0; }
.history li {
  position: relative;
  padding: 0 0 0 22px;
  font-size: .86rem;
  color: var(--ink-soft);
  line-height: 2;
}
.history li::before {
  content: "";
  position: absolute;
  left: 4px; top: .72em;
  width: 8px; height: 8px;
  border-radius: 50%;
  background: var(--card);
  border: 2px solid var(--leaf);
}
.history li::after {
  content: "";
  position: absolute;
  left: 9px; top: 1.5em; bottom: -.4em;
  width: 2px;
  background: var(--line);
}
.history li:last-child::after { display: none; }

.actions { display: flex; flex-wrap: wrap; gap: 9px; }
.btn {
  appearance: none;
  font: inherit;
  font-size: .86rem;
  font-weight: 800;
  cursor: pointer;
  border-radius: var(--r-pill);
  padding: 11px 18px;
  border: 1.5px solid transparent;
  display: inline-flex;
  align-items: center;
  gap: 8px;
  transition: transform .25s var(--ease-bounce), box-shadow .2s, background .2s, color .2s;
}
.btn--primary {
  background: var(--moss);
  color: #fff;
  box-shadow: 0 3px 0 var(--moss-deep);
}
.btn--primary:hover { background: var(--moss-deep); }
.btn--primary:active { transform: translateY(3px); box-shadow: 0 0 0 var(--moss-deep); }
.btn--ghost {
  background: var(--card);
  color: var(--ink);
  border-color: var(--line-strong);
  box-shadow: 0 3px 0 var(--line);
}
.btn--ghost:hover { background: var(--butter-wash); border-color: var(--butter); }
.btn--ghost:active { transform: translateY(3px); box-shadow: none; }
.btn--quiet {
  background: transparent;
  color: var(--moss-deep);
  border-color: var(--line-strong);
  padding: 9px 14px;
  font-size: .8rem;
}
.btn--quiet:hover { background: var(--moss-wash); }
.btn[disabled] { opacity: .45; cursor: not-allowed; }
.btn[disabled]:active { transform: none; }

/* ------------------------------------------------------------
   All-done state
   ------------------------------------------------------------ */
.alldone {
  margin-top: 18px;
  background:
    radial-gradient(circle at 88% 12%, var(--butter-wash), transparent 42%),
    var(--moss-wash);
  border: 1.5px solid #c7d8a6;
  border-radius: var(--r-lg);
  padding: 26px 22px;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 18px;
  text-align: center;
  box-shadow: var(--shadow-soft);
  animation: pop-in .5s var(--ease-bounce) both;
}
.alldone[hidden] { display: none; }
.alldone__art { width: 132px; height: 132px; flex: none; }
.alldone__art svg { width: 100%; height: 100%; }
.alldone__body { max-width: 42ch; }
.alldone h3 {
  font-family: var(--font);
  font-size: clamp(1.5rem, 5vw, 2rem);
  letter-spacing: -.02em;
  margin: 8px 0 10px;
  line-height: 1.1;
}
.alldone p { margin: 0 0 16px; color: var(--ink-soft); font-size: .94rem; }
.alldone .eyebrow { margin-bottom: 0; }

/* ------------------------------------------------------------
   Sidebar sections
   ------------------------------------------------------------ */
.sidebar { display: grid; gap: 18px; align-content: start; }

.rhythm, .key {
  background: var(--card);
  border: 1.5px solid var(--line);
  border-radius: var(--r-lg);
  padding: 20px;
  box-shadow: var(--shadow-soft);
}
.rhythm__top { display: flex; align-items: flex-start; justify-content: space-between; gap: 12px; }
.section-title {
  font-family: var(--font);
  font-size: 1.3rem;
  letter-spacing: -.02em;
  margin: 4px 0 0;
  line-height: 1.15;
}
.rhythm__total {
  flex: none;
  width: 48px; height: 48px;
  display: grid;
  place-items: center;
  background: var(--butter-wash);
  color: #8a6810;
  border-radius: 48% 52% 46% 54% / 55% 45% 55% 45%;
  font-family: var(--font);
  font-weight: 700;
  font-size: 1.3rem;
  transform: rotate(6deg);
  box-shadow: inset 0 -3px 0 rgba(138, 104, 16, .12);
}
.rhythm__chart {
  display: grid;
  grid-template-columns: repeat(7, 1fr);
  align-items: end;
  gap: 8px;
  height: 128px;
  margin: 22px 0 6px;
  padding-bottom: 22px;
  border-bottom: 2px dashed var(--line-strong);
  position: relative;
}
.day {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: flex-end;
  gap: 8px;
  height: 100%;
}
.day__stack {
  width: 100%;
  display: flex;
  flex-direction: column-reverse;
  gap: 4px;
  align-items: center;
  justify-content: flex-start;
}
.seed {
  width: min(100%, 26px);
  height: 22px;
  border-radius: 50% 50% 46% 54% / 60% 58% 42% 40%;
  animation: seed-grow .55s var(--ease-bounce) both;
  box-shadow: inset 0 -3px 0 rgba(63, 52, 36, .1);
}
.seed--water { background: var(--sky); }
.seed--tend  { background: var(--leaf-light); }
@keyframes seed-grow {
  from { transform: scale(0) translateY(8px); opacity: 0; }
  to   { transform: none; opacity: 1; }
}
.day__label {
  position: absolute;
  bottom: -20px;
  font-size: .66rem;
  font-weight: 800;
  letter-spacing: .08em;
  text-transform: uppercase;
  color: var(--ink-faint);
}
.day--peak .day__label { color: var(--clay-deep); }
.day--empty .day__label { opacity: .55; }
.rhythm__caption {
  margin: 30px 0 16px;
  font-size: .84rem;
  color: var(--ink-soft);
  line-height: 1.6;
}
.rhythm__legend { margin: 0; display: grid; gap: 8px; }
.rhythm__legend > div { display: flex; align-items: baseline; justify-content: space-between; gap: 10px; }
.rhythm__legend dt { font-size: .82rem; font-weight: 700; display: flex; align-items: center; gap: 8px; }
.rhythm__legend dd { margin: 0; font-size: .76rem; color: var(--ink-faint); font-style: italic; font-family: var(--font); }
.key-dot { width: 11px; height: 11px; border-radius: 46% 54% 50% 50% / 55% 45% 55% 45%; flex: none; }
.key-dot--water { background: var(--sky); }
.key-dot--tend { background: var(--leaf-light); }

/* Companion speech bubble */
.companion {
  position: relative;
  background: var(--moss);
  color: var(--paper-2);
  border-radius: 32px 32px 32px 10px;
  padding: 20px 22px 64px;
  box-shadow: var(--shadow-lift);
  overflow: visible;
}
.companion::before {
  content: "";
  position: absolute;
  inset: 6px;
  border: 1.5px dashed rgba(255, 255, 255, .18);
  border-radius: 26px 26px 26px 6px;
  pointer-events: none;
}
.companion__speech {
  font-family: var(--font);
  font-size: 1.08rem;
  line-height: 1.5;
  margin: 0;
  position: relative;
  z-index: 1;
}
.companion__figure {
  position: absolute;
  right: 14px; bottom: -14px;
  width: 84px; height: 84px;
  filter: drop-shadow(0 6px 6px rgba(20, 40, 18, .35));
}
.companion__figure svg { width: 100%; height: 100%; }

.key__list { list-style: none; margin: 12px 0 0; padding: 0; display: grid; gap: 10px; }
.key__list li { font-size: .84rem; color: var(--ink-soft); display: flex; align-items: center; gap: 8px; flex-wrap: wrap; }
.key__list b { color: var(--ink); }
kbd {
  font-family: var(--font-ui);
  font-size: .7rem;
  font-weight: 800;
  background: var(--paper-2);
  border: 1.5px solid var(--line-strong);
  border-bottom-width: 3px;
  border-radius: 7px;
  padding: 2px 7px;
  color: var(--ink);
  white-space: nowrap;
}
.key__foot {
  margin: 16px 0 0;
  font-family: var(--font);
  font-style: italic;
  font-size: .84rem;
  color: var(--ink-faint);
}

.footer {
  display: flex;
  flex-wrap: wrap;
  justify-content: space-between;
  gap: 8px;
  margin-top: 40px;
  padding-top: 16px;
  border-top: 1.5px dashed var(--line-strong);
  font-size: .74rem;
  color: var(--ink-faint);
  letter-spacing: .04em;
}
.footer p { margin: 0; }
.footer__right span { color: var(--clay); }

/* ------------------------------------------------------------
   Toast + undo
   ------------------------------------------------------------ */
.toast {
  position: fixed;
  z-index: 50;
  left: 50%;
  bottom: max(18px, env(safe-area-inset-bottom));
  transform: translate(-50%, 0);
  width: min(calc(100% - 28px), 440px);
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 12px 12px 12px 18px;
  background: var(--ink);
  color: var(--paper-2);
  border-radius: var(--r-pill);
  box-shadow: 0 14px 34px -10px rgba(20, 16, 10, .6);
  animation: toast-in .45s var(--ease-bounce) both;
}
.toast[hidden] { display: none; }
@keyframes toast-in {
  from { opacity: 0; transform: translate(-50%, 24px) scale(.95); }
  to   { opacity: 1; transform: translate(-50%, 0) scale(1); }
}
.toast.is-leaving { animation: toast-out .25s var(--ease-soft) both; }
@keyframes toast-out {
  to { opacity: 0; transform: translate(-50%, 16px) scale(.96); }
}
.toast__msg { margin: 0; flex: 1; font-size: .88rem; line-height: 1.35; }
.toast__msg b { color: var(--butter); }
.toast__undo {
  appearance: none;
  flex: none;
  border: 0;
  background: var(--butter);
  color: #4a3608;
  font: inherit;
  font-size: .82rem;
  font-weight: 800;
  padding: 9px 15px;
  border-radius: var(--r-pill);
  cursor: pointer;
  display: inline-flex;
  gap: 6px;
  align-items: center;
  transition: transform .2s var(--ease-bounce), background .2s;
}
.toast__undo:hover { background: #f3cb6b; transform: translateY(-2px); }
.toast__close {
  appearance: none;
  flex: none;
  border: 0;
  background: transparent;
  color: rgba(255, 255, 255, .55);
  font-size: .9rem;
  width: 28px; height: 28px;
  border-radius: 50%;
  cursor: pointer;
}
.toast__close:hover { background: rgba(255, 255, 255, .12); color: #fff; }

/* ------------------------------------------------------------
   Focus visibility — one clear, consistent ring everywhere
   ------------------------------------------------------------ */
:where(a, button, [tabindex]):focus-visible {
  outline: 3px solid var(--clay);
  outline-offset: 3px;
  border-radius: 6px;
}
.card__head:focus-visible { outline-offset: -4px; border-radius: var(--r-lg); }
.seg:focus-visible, .toast__undo:focus-visible, .toast__close:focus-visible { outline-color: var(--butter); }
.companion :focus-visible { outline-color: var(--butter); }

/* ------------------------------------------------------------
   Dark mode — warm potting-soil tones, not inverted grey
   ------------------------------------------------------------ */
@media (prefers-color-scheme: dark) {
  :root {
    --paper: #241e17;
    --paper-2: #2c251c;
    --card: #332b20;
    --ink: #f3ead7;
    --ink-soft: #c6b9a2;
    --ink-faint: #938672;
    --moss: #8fb27e;
    --moss-deep: #b7d29c;
    --moss-wash: #3a4a30;
    --leaf: #9bc07c;
    --leaf-light: #6f8a55;
    --clay: #e89872;
    --clay-deep: #f3b493;
    --clay-wash: #4a2f22;
    --butter: #e6bd5c;
    --butter-wash: #4a3c1e;
    --sky: #8fc0c6;
    --sky-wash: #2c4141;
    --line: #463c2d;
    --line-strong: #5c4e39;
    --shadow-soft: 0 2px 0 rgba(0, 0, 0, .2), 0 10px 24px -14px rgba(0, 0, 0, .7);
    --shadow-lift: 0 3px 0 rgba(0, 0, 0, .25), 0 18px 34px -16px rgba(0, 0, 0, .8);
  }
  body::before { opacity: .25; }
  .canvas-blob--a { opacity: .16; }
  .canvas-blob--b { opacity: .14; }
  .canvas-blob--c { opacity: .1; }
  .brand__mark { background: var(--moss); }
  .brand__mark::before, .brand__mark::after { background: var(--paper); }
  .seg[aria-pressed="true"] { background: var(--paper-2); color: var(--ink); box-shadow: 0 2px 0 rgba(0, 0, 0, .4); }
  .seg[aria-pressed="true"] .seg__count { background: rgba(255, 255, 255, .1); }
  .btn--primary { color: #1c2718; box-shadow: 0 3px 0 #2c3f26; }
  .btn--primary:hover { background: #a4c791; }
  .btn--ghost { background: var(--paper-2); }
  .card--done { background: var(--paper-2); }
  .badge--overdue { color: var(--clay-deep); }
  .badge--later { color: var(--sky); }
  .badge--snoozed { color: var(--butter); }
  .rhythm__total { color: var(--butter); }
  .toast { background: #0f0c08; }
  .companion { background: #3c5233; }
  .alldone { border-color: #566b3c; }
  .btn--primary { color: #14200f; }
}

/* ------------------------------------------------------------
   Desktop — two genuinely different columns, not a stretched phone
   ------------------------------------------------------------ */
@media (min-width: 900px) {
  .frame { padding-top: 52px; }
  .brand { padding-bottom: 44px; }
  .layout {
    grid-template-columns: minmax(0, 1.55fr) minmax(300px, .9fr);
    gap: clamp(28px, 4vw, 56px);
    align-items: start;
  }
  .sidebar {
    position: sticky;
    top: 32px;
    gap: 22px;
  }
  .queue__intro { padding-right: 6%; }
  .greeting { font-size: clamp(2.8rem, 4vw, 3.8rem); }
  .lede { font-size: 1.05rem; }
  .cards { gap: 16px; }
  .card__head { grid-template-columns: 76px 1fr auto; padding: 16px 20px 16px 22px; }
  .card__art { width: 76px; height: 76px; }
  .card__name { font-size: 1.5rem; }
  .facts { grid-template-columns: repeat(3, 1fr); }
  .fact:first-child { grid-column: auto; }
  .alldone { flex-direction: row; text-align: left; padding: 30px 34px; gap: 28px; }
  .alldone__art { width: 168px; height: 168px; }
  .alldone__body { max-width: 46ch; }
  .rhythm, .key { padding: 24px; }
  .companion { padding: 24px 26px 72px; }
  .companion__speech { font-size: 1.16rem; }
}

@media (min-width: 1180px) {
  .companion__figure { width: 96px; height: 96px; right: 20px; }
  .rhythm__chart { height: 140px; }
}

/* ------------------------------------------------------------
   Reduced motion — keep all meaning, drop all movement
   ------------------------------------------------------------ */
@media (prefers-reduced-motion: reduce) {
  html { scroll-behavior: auto; }
  *, *::before, *::after {
    animation-duration: .001ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: .001ms !important;
    scroll-behavior: auto !important;
  }
  .card__detail, .card__head[aria-expanded="true"] + .card__detail { transition: none; }
  .seed, .card--fresh, .alldone, .toast { animation: none !important; }
}

/* Compact phones */
@media (max-width: 360px) {
  .card__head { grid-template-columns: 52px 1fr; padding-left: 14px; }
  .card__art { width: 52px; height: 52px; }
  .card__meta { grid-column: 2; flex-direction: row; align-items: center; }
  .badge { font-size: .62rem; }
  .rhythm__chart { gap: 5px; }
}

/* ============================================================
   Moss — behaviour and illustration
   Vanilla JS. No network, no build, no dependencies.
   The dataset below mirrors PLANTS.json verbatim; it is inlined so
   the screen also works from file:// without fetch/XHR.
   ============================================================ */
(function () {
  "use strict";

  var DATA = {
    plants: [
      {"id":"fern","name":"Frida","species":"Boston fern","location":"Bathroom","task":"Water","due":"2 days overdue","urgency":4,"light":"Low, indirect","history":["Sep 19 · Misted","Sep 16 · Watered","Sep 12 · New frond"]},
      {"id":"pothos","name":"Orbit","species":"Golden pothos","location":"Bookshelf","task":"Rotate","due":"Today","urgency":2,"light":"Medium, indirect","history":["Sep 20 · Watered","Sep 14 · Rotated","Sep 10 · Wiped leaves"]},
      {"id":"cactus","name":"Dot","species":"Bunny ears cactus","location":"South window","task":"Check soil","due":"Today","urgency":1,"light":"Bright, direct","history":["Sep 08 · Watered","Sep 01 · New pad noted","Aug 22 · Rotated"]},
      {"id":"calathea","name":"Drama","species":"Calathea orbifolia","location":"Bedroom","task":"Mist","due":"Tomorrow","urgency":0,"light":"Medium, filtered","history":["Sep 21 · Misted","Sep 18 · Watered","Sep 15 · Brown edge noted"]}
    ],
    week: [1, 3, 2, 4, 2, 1, 3]
  };

  /* ---------- tiny helpers ---------- */
  var $ = function (sel) { return document.querySelector(sel); };
  var byId = function (id) {
    for (var i = 0; i < DATA.plants.length; i++) {
      if (DATA.plants[i].id === id) return DATA.plants[i];
    }
    return null;
  };
  var esc = function (s) {
    return String(s).replace(/&/g, "&amp;").replace(/</g, "&lt;")
      .replace(/>/g, "&gt;").replace(/"/g, "&quot;");
  };

  /* ============================================================
     Illustrations — all inline SVG, drawn from primitives
     ============================================================ */
  function svg(inner) {
    return '<svg viewBox="0 0 100 100" aria-hidden="true" focusable="false" ' +
           'xmlns="http://www.w3.org/2000/svg">' + inner + '</svg>';
  }

  function pot(clay, rim) {
    clay = clay || "#cf7f57"; rim = rim || "#b0603a";
    return '<path d="M28 70 h44 l-5 24 a5 5 0 0 1 -5 4 H38 a5 5 0 0 1 -5 -4 Z" fill="' + clay + '"/>' +
           '<rect x="24" y="66" width="52" height="9" rx="4" fill="' + rim + '"/>' +
           '<path d="M30 75 h40 l-1 4 H31 Z" fill="' + rim + '" opacity=".45"/>';
  }

  function quad(p0, p1, p2, t) {
    var m = 1 - t;
    return {
      x: m * m * p0.x + 2 * m * t * p1.x + t * t * p2.x,
      y: m * m * p0.y + 2 * m * t * p1.y + t * t * p2.y
    };
  }
  function quadD(p0, p1, p2, t) {
    return { x: 2 * (1 - t) * (p1.x - p0.x) + 2 * t * (p2.x - p1.x),
             y: 2 * (1 - t) * (p1.y - p0.y) + 2 * t * (p2.y - p1.y) };
  }

  /* Frida — a fan of feathered fern fronds */
  function fernArt() {
    var angles = [-54, -27, 0, 27, 54], out = "";
    angles.forEach(function (a, idx) {
      var rad = a * Math.PI / 180;
      var L = 52 - Math.abs(a) * 0.14;
      var p0 = { x: 50, y: 69 };
      var p2 = { x: 50 + Math.sin(rad) * L, y: 69 - Math.cos(rad) * L };
      var p1 = { x: 50 + Math.sin(rad) * L * 0.34 + Math.sin(rad) * 9,
                 y: 69 - Math.cos(rad) * L * 0.6 };
      var green = idx % 2 ? "#6f9e5a" : "#4f7a4a";
      out += '<path d="M' + p0.x + ' ' + p0.y + ' Q' + p1.x.toFixed(1) + ' ' +
             p1.y.toFixed(1) + ' ' + p2.x.toFixed(1) + ' ' + p2.y.toFixed(1) +
             '" fill="none" stroke="' + green + '" stroke-width="2.2" stroke-linecap="round"/>';
      for (var i = 1; i <= 6; i++) {
        var t = i / 7;
        var q = quad(p0, p1, p2, t);
        var d = quadD(p0, p1, p2, t);
        var len = Math.sqrt(d.x * d.x + d.y * d.y) || 1;
        var px = -d.y / len, py = d.x / len;
        var sc = 1 - t * 0.42;
        [-1, 1].forEach(function (side) {
          var cx = q.x + px * 4.4 * side, cy = q.y + py * 4.4 * side;
          var ang = Math.atan2(py, px) * 180 / Math.PI;
          out += '<ellipse cx="' + cx.toFixed(1) + '" cy="' + cy.toFixed(1) +
                 '" rx="' + (5.6 * sc).toFixed(1) + '" ry="' + (2.5 * sc).toFixed(1) +
                 '" fill="' + green + '" opacity="' + (0.95 - t * 0.18).toFixed(2) +
                 '" transform="rotate(' + ang.toFixed(1) + ' ' + cx.toFixed(1) + ' ' + cy.toFixed(1) + ')"/>';
        });
      }
    });
    return svg(out + pot("#cf7f57", "#b0603a"));
  }

  /* Orbit — a trailing vine with heart-shaped leaves */
  function pothosArt() {
    var leaf = function (x, y, rot, sc, fill) {
      return '<g transform="translate(' + x + ' ' + y + ') rotate(' + rot + ') scale(' + sc + ')">' +
             '<path d="M0 0 C -9 -11, -13 4, 0 11 C 13 4, 9 -11, 0 0 Z" fill="' + fill + '"/>' +
             '<path d="M0 1 L0 9" stroke="#3c6139" stroke-width="1.3" fill="none" opacity=".7"/>' +
             '</g>';
    };
    var out =
      '<path d="M50 12 C 30 24, 72 38, 46 66" fill="none" stroke="#4f7a4a" stroke-width="2.4" stroke-linecap="round"/>' +
      '<path d="M50 12 C 62 18, 66 26, 60 34" fill="none" stroke="#6f9e5a" stroke-width="2" stroke-linecap="round"/>';
    out += leaf(48, 20, -8, 0.85, "#7fae66");
    out += leaf(33, 30, -38, 0.95, "#6f9e5a");
    out += leaf(65, 39, 40, 1.05, "#4f7a4a");
    out += leaf(40, 49, -18, 0.9, "#7fae66");
    out += leaf(58, 57, 30, 0.8, "#6f9e5a");
    return svg(out + pot("#d38a5f", "#b96f43"));
  }

  /* Dot — stacked bunny-ear pads with tiny spine dots */
  function cactusArt() {
    var pads = [
      { x: 42, y: 47, rx: 12, ry: 17, r: -14, c: "#6f9e5a" },
      { x: 60, y: 37, rx: 11, ry: 15, r: 17, c: "#7fae66" },
      { x: 55, y: 60, rx: 9, ry: 12, r: 25, c: "#8cba72" }
    ];
    var out = "";
    pads.forEach(function (p) {
      out += '<g transform="rotate(' + p.r + ' ' + p.x + ' ' + p.y + ')">' +
             '<ellipse cx="' + p.x + '" cy="' + p.y + '" rx="' + p.rx + '" ry="' + p.ry + '" fill="' + p.c + '"/>' +
             '<ellipse cx="' + (p.x - 2) + '" cy="' + (p.y - 3) + '" rx="' + (p.rx - 3) +
             '" ry="' + (p.ry - 4) + '" fill="#a9c47f" opacity=".35"/>';
      for (var i = -2; i <= 2; i++) {
        out += '<circle cx="' + (p.x + i * 3.6) + '" cy="' + (p.y - 8 + Math.abs(i) * 1.6) +
               '" r="1.15" fill="#e9e0b8"/>' +
               '<circle cx="' + (p.x + i * 3.6) + '" cy="' + (p.y + 2 + Math.abs(i) * 1.6) +
               '" r="1.15" fill="#e9e0b8"/>';
      }
      out += '</g>';
    });
    return svg(out + pot("#c98a63", "#a96843"));
  }

  /* Drama — big striped oval leaves on fine stems */
  function calatheaArt() {
    var out = "";
    var leaves = [
      { x: 33, y: 40, r: -26, c: "#6f9e5a" },
      { x: 67, y: 38, r: 24, c: "#4f7a4a" },
      { x: 50, y: 32, r: -2, c: "#7fae66" }
    ];
    leaves.forEach(function (l) {
      out += '<path d="M50 68 Q' + ((50 + l.x) / 2) + ' 56 ' + l.x + ' ' + l.y +
             '" fill="none" stroke="#4f7a4a" stroke-width="2" stroke-linecap="round"/>';
    });
    leaves.forEach(function (l) {
      out += '<g transform="translate(' + l.x + ' ' + l.y + ') rotate(' + l.r + ')">' +
             '<ellipse cx="0" cy="0" rx="14" ry="22" fill="' + l.c + '"/>' +
             '<ellipse cx="0" cy="0" rx="14" ry="22" fill="#a9c47f" opacity=".18"/>' +
             '<path d="M-1 -20 L-1 20" stroke="#cfe0a8" stroke-width="1.4" opacity=".8"/>' +
             '<path d="M-11 -11 Q0 -15 11 -11" stroke="#cfe0a8" stroke-width="1.4" fill="none" opacity=".65"/>' +
             '<path d="M-12 -3 Q0 -7 12 -3" stroke="#cfe0a8" stroke-width="1.4" fill="none" opacity=".65"/>' +
             '<path d="M-11 6 Q0 2 11 6" stroke="#cfe0a8" stroke-width="1.4" fill="none" opacity=".65"/>' +
             '<path d="M-8 13 Q0 10 8 13" stroke="#cfe0a8" stroke-width="1.4" fill="none" opacity=".65"/>' +
             '</g>';
    });
    return svg(out + pot("#cf7f57", "#b0603a"));
  }

  var ART = { fern: fernArt, pothos: pothosArt, cactus: cactusArt, calathea: calatheaArt };
  var ART_BG = { fern: "#e3eccc", pothos: "#f7e7b8", cactus: "#f6ddcb", calathea: "#dbe9e6" };

  /* A small companion character, and its celebratory cousin */
  function mascotArt(big) {
    var spark = big
      ? '<g fill="#e9b84a"><path d="M18 22 l2 5 5 2 -5 2 -2 5 -2 -5 -5 -2 5 -2 Z"/>' +
        '<path d="M82 30 l1.5 4 4 1.5 -4 1.5 -1.5 4 -1.5 -4 -4 -1.5 4 -1.5 Z"/>' +
        '<circle cx="76" cy="14" r="2"/><circle cx="22" cy="48" r="1.8"/></g>'
      : '';
    var out = spark +
      '<path d="M30 62 h40 l-5 30 a6 6 0 0 1 -6 5 H41 a6 6 0 0 1 -6 -5 Z" fill="#cf7f57"/>' +
      '<rect x="26" y="57" width="48" height="10" rx="5" fill="#b0603a"/>' +
      '<path d="M50 57 C 49 44, 49 38, 50 30" fill="none" stroke="#4f7a4a" stroke-width="3.4" stroke-linecap="round"/>' +
      '<path d="M50 44 C 38 44, 30 36, 32 27 C 40 26, 49 33, 50 44 Z" fill="#7fae66"/>' +
      '<path d="M50 40 C 62 40, 70 32, 68 23 C 60 22, 51 29, 50 40 Z" fill="#6f9e5a"/>' +
      '<circle cx="44" cy="76" r="2.2" fill="#3c3027"/>' +
      '<circle cx="56" cy="76" r="2.2" fill="#3c3027"/>' +
      '<path d="M45 83 Q50 88 55 83" fill="none" stroke="#3c3027" stroke-width="2" stroke-linecap="round"/>' +
      '<circle cx="38" cy="81" r="2.6" fill="#e89872" opacity=".55"/>' +
      '<circle cx="62" cy="81" r="2.6" fill="#e89872" opacity=".55"/>';
    if (big) {
      out += '<g transform="translate(70 62)"><circle r="12" fill="#4f7a4a"/>' +
             '<path d="M-5 0 l4 4 8 -9" fill="none" stroke="#f7f0e2" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"/></g>';
    }
    return svg(out);
  }

  /* ============================================================
     State
     ============================================================ */
  var state = {
    status: {},      // id -> 'todo' | 'snoozed' | 'done'
    expanded: null,  // one open card at a time
    filter: "all"
  };
  DATA.plants.forEach(function (p) { state.status[p.id] = "todo"; });

  var stack = [];            // undo history: {id, from, to}
  var pendingFocus = null;
  var toastTimer = null, leaveTimer = null;
  var cheerIndex = 0;
  var CHEERS = ["Lovely.", "Nicely done.", "She'll thank you quietly.", "One less thing.", "Good tending."];

  var DONE_LABEL = { fern: "Watered", pothos: "Rotated", cactus: "Checked", calathea: "Misted" };
  var DONE_VERB  = { fern: "watered", pothos: "rotated", cactus: "checked in on", calathea: "misted" };

  /* ---------- DOM refs ---------- */
  var queueList = $("#queue-list");
  var summary   = $("#summary");
  var lede      = $("#lede");
  var filterEl  = $("#filter");
  var live      = $("#live");
  var alldone   = $("#alldone");
  var toast     = $("#toast");
  var toastMsg  = $("#toast-msg");
  var toastUndo = $("#toast-undo");
  var toastClose= $("#toast-close");
  var speech    = $("#companion-speech");

  /* ============================================================
     Derived data
     ============================================================ */
  function dueCat(p) {
    if (/overdue/i.test(p.due)) return "overdue";
    if (/today/i.test(p.due)) return "today";
    return "later";
  }
  function rank(p) {
    var s = state.status[p.id];
    if (s === "done") return 100;
    if (s === "snoozed") return 50;
    return (dueCat(p) === "overdue" ? -100 : 0) - p.urgency;
  }
  function sorted() {
    return DATA.plants.slice().sort(function (a, b) { return rank(a) - rank(b); });
  }
  function passes(p, status) {
    status = status || state.status[p.id];
    if (state.filter === "all") return true;
    if (state.filter === "todo") return status !== "done";
    return status === "done";
  }
  function visible() { return sorted().filter(function (p) { return passes(p); }); }
  function todoCount() {
    return DATA.plants.filter(function (p) { return state.status[p.id] !== "done"; }).length;
  }
  function doneCount() {
    return DATA.plants.filter(function (p) { return state.status[p.id] === "done"; }).length;
  }

  /* ============================================================
     Card markup
     ============================================================ */
  function badgeHTML(p) {
    var s = state.status[p.id], cls, txt;
    if (s === "done")        { cls = "badge--done";    txt = "All done"; }
    else if (s === "snoozed"){ cls = "badge--snoozed"; txt = "Snoozed"; }
    else if (dueCat(p) === "overdue") { cls = "badge--overdue"; txt = p.due; }
    else if (dueCat(p) === "today")   { cls = "badge--today";   txt = "Today"; }
    else                              { cls = "badge--later";   txt = "Tomorrow"; }
    return '<span class="badge ' + cls + '">' + esc(txt) + "</span>";
  }

  function actionsHTML(p) {
    var s = state.status[p.id], id = esc(p.id), out = '<div class="actions">';
    if (s !== "done") {
      out += '<button type="button" class="btn btn--primary" data-role="done" data-id="' + id +
             '" data-fk="action:' + id + ':done" aria-label="Mark ' + esc(p.name) + '\'s ' +
             esc(p.task.toLowerCase()) + ' as done">✓ ' + esc(DONE_LABEL[p.id]) + "</button>";
    }
    if (s === "todo") {
      out += '<button type="button" class="btn btn--ghost" data-role="snooze" data-id="' + id +
             '" data-fk="action:' + id + ':snooze" aria-label="Snooze ' + esc(p.name) +
             ' until later">☾ Snooze</button>';
    } else {
      var label = s === "done" ? "Bring back" : "Back to today";
      out += '<button type="button" class="btn btn--ghost" data-role="restore" data-id="' + id +
             '" data-fk="action:' + id + ':restore" aria-label="Bring ' + esc(p.name) +
             ' back to the care queue">↶ ' + label + "</button>";
    }
    return out + "</div>";
  }

  function detailHTML(p) {
    var hist = p.history.map(function (h) { return "<li>" + esc(h) + "</li>"; }).join("");
    return '<dl class="facts">' +
      '<div class="fact"><dt><span class="fact__icon" aria-hidden="true">☀</span> Light</dt><dd>' + esc(p.light) + "</dd></div>" +
      '<div class="fact"><dt><span class="fact__icon" aria-hidden="true">⌂</span> Spot</dt><dd>' + esc(p.location) + "</dd></div>" +
      '<div class="fact"><dt><span class="fact__icon" aria-hidden="true">✿</span> Care</dt><dd>' + esc(p.task) + " · " + esc(p.due) + "</dd></div>" +
      "</dl>" +
      '<p class="history-title">Little observations</p>' +
      '<ul class="history">' + hist + "</ul>" +
      actionsHTML(p);
  }

  function cardHTML(p) {
    var s = state.status[p.id];
    var open = state.expanded === p.id;
    var cls = "card ";
    if (s === "done") cls += "card--done";
    else if (s === "snoozed") cls += "card--snoozed";
    else cls += "card--" + dueCat(p);
    var id = esc(p.id);
    var label = esc(p.name) + ", " + esc(p.species) + ". " + esc(p.task) + ", " + esc(p.due) +
                ". Show care notes and actions.";
    return '<li class="' + cls + '" data-id="' + id + '" style="--art-bg:' + ART_BG[p.id] + '">' +
      '<button type="button" class="card__head" data-role="toggle" data-id="' + id +
        '" data-fk="head:' + id + '" aria-expanded="' + open + '" aria-controls="detail-' + id +
        '" aria-label="' + label + '">' +
        '<span class="card__art" aria-hidden="true">' + ART[p.id]() + "</span>" +
        '<span class="card__id">' +
          '<span class="card__namerow"><span class="card__name">' + esc(p.name) + "</span>" +
          '<span class="card__species">' + esc(p.species) + "</span></span>" +
          '<span class="card__task"><b>' + esc(p.task) + "</b> · " + esc(p.location) + "</span>" +
        "</span>" +
        '<span class="card__meta">' + badgeHTML(p) +
          '<span class="card__chevron" aria-hidden="true">⌄</span></span>' +
      "</button>" +
      '<div class="card__detail" id="detail-' + id + '"' + (open ? "" : ' inert aria-hidden="true"') + ">" +
        '<div class="card__detail-inner"><div class="card__detail-pad">' + detailHTML(p) + "</div></div>" +
      "</div>" +
    "</li>";
  }

  /* ============================================================
     Render
     ============================================================ */
  function renderCounts() {
    var t = todoCount(), d = doneCount();
    $("#count-all").textContent = DATA.plants.length;
    $("#count-todo").textContent = t;
    $("#count-done").textContent = d;
  }
  function renderFilters() {
    Array.prototype.forEach.call(filterEl.querySelectorAll(".seg"), function (b) {
      b.setAttribute("aria-pressed", String(b.dataset.filter === state.filter));
      b.dataset.fk = "filter:" + b.dataset.filter;
    });
  }
  function renderSummary() {
    var c = { overdue: 0, today: 0, later: 0 }, out = "";
    DATA.plants.forEach(function (p) {
      if (state.status[p.id] === "done") return;
      c[dueCat(p)]++;
    });
    if (c.overdue) out += '<span class="chip chip--overdue"><span class="chip__dot"></span>' + c.overdue + ' overdue</span>';
    if (c.today)   out += '<span class="chip chip--today"><span class="chip__dot"></span>' + c.today + ' today</span>';
    if (c.later)   out += '<span class="chip chip--later"><span class="chip__dot"></span>' + c.later + ' coming up</span>';
    if (!out)      out = '<span class="chip"><span class="chip__dot" style="background:var(--leaf)"></span>all caught up</span>';
    summary.innerHTML = out;
  }
  function renderLede() {
    var t = todoCount();
    if (t === 0) lede.textContent = "Everyone is looked after. Nothing left on the list — enjoy the quiet.";
    else if (t === 1) lede.textContent = "One little thing is waiting. Nothing here is urgent in the big way — just in the leafy way.";
    else lede.textContent = t + " little things are waiting. Nothing here is urgent in the big way — just in the leafy way.";
  }
  function renderQueue() {
    var list = visible();
    queueList.innerHTML = list.map(cardHTML).join("");
  }
  function renderAllDone() {
    alldone.hidden = !(doneCount() === DATA.plants.length && state.filter !== "done");
  }
  function renderCompanion() {
    var t = todoCount();
    var fridaOverdue = state.status.fern !== "done" && /overdue/.test(byId("fern").due);
    var msg;
    if (t === 0) msg = "Look at you. Everyone's happy. I'll keep an eye on them till tomorrow — go put the kettle on.";
    else if (fridaOverdue) msg = "Psst. Frida's been waiting two days. She's dramatic about soil, but she has a point.";
    else if (stack.length) msg = "No rush. Snoozed and done things can always be brought back — nothing here is permanent.";
    else msg = "Just a couple of small things left. Slow is a perfectly good speed for a morning.";
    speech.textContent = msg;
  }
  function render() {
    renderCounts(); renderFilters(); renderSummary(); renderLede();
    renderQueue(); renderAllDone(); renderCompanion();
  }

  /* ---------- focus preservation across re-renders ---------- */
  function captureFocus() {
    var a = document.activeElement;
    return a && a.dataset && a.dataset.fk ? a.dataset.fk : null;
  }
  function reRender(preferred) {
    pendingFocus = preferred || captureFocus();
    render();
    restoreFocus();
  }
  function restoreFocus() {
    var chain = [];
    if (pendingFocus) chain.push(pendingFocus);
    chain.push("filter:" + state.filter);
    for (var i = 0; i < chain.length; i++) {
      var el = document.querySelector('[data-fk="' + chain[i] + '"]');
      if (el && !el.closest("[inert]") && el.offsetParent !== null) {
        el.focus(); pendingFocus = null; return;
      }
    }
    var first = queueList.querySelector(".card__head");
    if (first && first.offsetParent !== null) first.focus();
    else {
      var seg = filterEl.querySelector('.seg[aria-pressed="true"]');
      if (seg) seg.focus();
    }
    pendingFocus = null;
  }

  /* ============================================================
     Announcements & toast
     ============================================================ */
  function announce(msg) {
    live.textContent = "";
    window.setTimeout(function () { live.textContent = msg; }, 60);
  }
  function hideToast(immediate) {
    window.clearTimeout(toastTimer);
    window.clearTimeout(leaveTimer);
    if (immediate || toast.hidden) { toast.hidden = true; toast.classList.remove("is-leaving"); return; }
    toast.classList.add("is-leaving");
    leaveTimer = window.setTimeout(function () {
      toast.hidden = true; toast.classList.remove("is-leaving");
    }, 260);
  }
  function showToast(html) {
    window.clearTimeout(toastTimer);
    window.clearTimeout(leaveTimer);
    toast.classList.remove("is-leaving");
    toastMsg.innerHTML = html;
    toast.hidden = false;
    toastTimer = window.setTimeout(function () { hideToast(false); }, 6500);
  }

  /* ============================================================
     Actions
     ============================================================ */
  function neighborFocus(id) {
    var ids = visible().map(function (p) { return p.id; });
    var i = ids.indexOf(id);
    var nb = ids[i + 1] || ids[i - 1];
    return nb ? "head:" + nb : "filter:" + state.filter;
  }

  function setStatus(id, status, push) {
    var prev = state.status[id];
    if (prev === status) return false;
    state.status[id] = status;
    if (push) stack.push({ id: id, from: prev, to: status });
    return true;
  }

  function handleAction(id, role) {
    var p = byId(id);
    if (!p) return;
    var status = role === "done" ? "done" : "snoozed";
    var stillVisible = passes(p, status);
    var pref = stillVisible ? "head:" + id : neighborFocus(id);
    if (!setStatus(id, status, true)) return;

    var html;
    if (role === "done") {
      html = "<b>" + esc(p.name) + "</b> " + esc(DONE_VERB[id]) + ". " +
             esc(CHEERS[cheerIndex++ % CHEERS.length]);
    } else {
      html = "<b>" + esc(p.name) + "</b> snoozed till later. No rush at all.";
    }
    reRender(pref);
    showToast(html);
  }

  function undoById(id) {
    var idx = -1;
    for (var i = stack.length - 1; i >= 0; i--) { if (stack[i].id === id) { idx = i; break; } }
    var from = idx >= 0 ? stack[idx].from : "todo";
    stack = stack.filter(function (e) { return e.id !== id; });
    setStatus(id, from, false);
    if (state.filter === "done") state.filter = "todo";
    hideToast(true);
    var p = byId(id);
    announce(esc(p.name) + " is back on your list. " + todoCount() + " to tend.");
    reRender("head:" + id);
  }

  function undoLast() {
    var e = stack.pop();
    if (!e) { announce("Nothing left to undo."); hideToast(true); return; }
    setStatus(e.id, e.from, false);
    if (state.filter === "done") state.filter = "todo";
    hideToast(true);
    var p = byId(e.id);
    announce(esc(p.name) + " is back on your list. " + todoCount() + " to tend.");
    reRender("head:" + e.id);
  }

  /* ============================================================
     Weekly rhythm
     ============================================================ */
  function renderRhythm() {
    var labels = ["M", "T", "W", "T", "F", "S", "S"];
    var total = DATA.week.reduce(function (a, b) { return a + b; }, 0);
    var max = Math.max.apply(null, DATA.week);
    var chart = $("#rhythm-chart");
    var html = "";
    DATA.week.forEach(function (n, day) {
      var seeds = "";
      for (var i = 0; i < n; i++) {
        var type = i % 2 === 0 ? "water" : "tend";
        seeds += '<span class="seed seed--' + type + '" style="animation-delay:' +
                 (day * 60 + i * 70) + 'ms"></span>';
      }
      var dayCls = "day" + (n === max ? " day--peak" : "") + (n === 0 ? " day--empty" : "");
      html += '<div class="' + dayCls + '">' +
                '<div class="day__stack">' + seeds + "</div>" +
                '<span class="day__label" aria-hidden="true">' + labels[day] + "</span>" +
              "</div>";
    });
    chart.innerHTML = html;
    var totalEl = $("#rhythm-total");
    totalEl.textContent = total;
    totalEl.setAttribute("aria-label", total + " moments of care this week");
    chart.setAttribute("aria-label", "Care moments this week, Monday through Sunday: " +
      DATA.week.map(function (n, i) {
        return ["Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday", "Sunday"][i] + " " + n;
      }).join(", ") + ". Total " + total + ".");
  }

  /* ============================================================
     Events
     ============================================================ */
  queueList.addEventListener("click", function (e) {
    var toggle = e.target.closest('[data-role="toggle"]');
    if (toggle) {
      var tid = toggle.dataset.id;
      state.expanded = state.expanded === tid ? null : tid;
      reRender("head:" + tid);
      return;
    }
    var act = e.target.closest("[data-role]");
    if (!act) return;
    var role = act.dataset.role, id = act.dataset.id;
    if (role === "done" || role === "snooze") handleAction(id, role);
    else if (role === "restore") undoById(id);
  });

  queueList.addEventListener("keydown", function (e) {
    var heads = Array.prototype.slice.call(queueList.querySelectorAll(".card__head"));
    var i = heads.indexOf(document.activeElement);
    if (i < 0) return;
    var j = null;
    if (e.key === "ArrowDown") j = (i + 1) % heads.length;
    else if (e.key === "ArrowUp") j = (i - 1 + heads.length) % heads.length;
    else if (e.key === "Home") j = 0;
    else if (e.key === "End") j = heads.length - 1;
    if (j !== null) { e.preventDefault(); heads[j].focus(); }
  });

  filterEl.addEventListener("click", function (e) {
    var b = e.target.closest(".seg");
    if (!b) return;
    state.filter = b.dataset.filter;
    state.expanded = null;
    announce(state.filter === "all" ? "Showing all plants." :
             state.filter === "todo" ? "Showing plants still to tend." : "Showing finished plants.");
    reRender("filter:" + state.filter);
  });

  toastUndo.addEventListener("click", undoLast);
  toastClose.addEventListener("click", function () { hideToast(false); });
  $("#bring-back").addEventListener("click", function () {
    undoLast();
    var seg = filterEl.querySelector('.seg[data-filter="todo"]');
    if (seg) seg.focus();
  });
  document.addEventListener("keydown", function (e) {
    if (e.key === "Escape" && !toast.hidden) hideToast(false);
  });

  /* ============================================================
     Init
     ============================================================ */
  $("#mascot-slot").innerHTML = mascotArt(false);
  $("#companion-figure").innerHTML = mascotArt(false);
  $("#alldone-art").innerHTML = mascotArt(true);
  renderRhythm();
  render();
})();
